-- Per-org envelope encryption. Adds wrap fields to Org, replaces
-- plaintext PII columns on Member with encrypted Bytes columns +
-- a sort-bucket helper, and adds encryption flags to Photo.
--
-- No existing customer data — there are only demo seeds, which are
-- regenerated by `npm run db:seed`. Hence the destructive DROP COLUMN
-- on Member.firstName/lastName/phone.
--
-- The new Org wrap columns are nullable: legacy demo rows that survive
-- a migrate-without-reset will boot but cannot be unlocked until they
-- are re-provisioned. Seed handles fresh inserts via prisma/seed.ts.

-- 1. Org: add envelope-encryption columns.
ALTER TABLE "Org"
  ADD COLUMN "encryptedDek"           bytea,
  ADD COLUMN "passphraseWrappedDek"   bytea,
  ADD COLUMN "passphraseSalt"         bytea,
  ADD COLUMN "passphraseVerifier"     text,
  ADD COLUMN "recoveryWrappedDek"     bytea,
  ADD COLUMN "recoverySalt"           bytea,
  ADD COLUMN "recoveryVerifier"       text,
  ADD COLUMN "keyVersion"             integer NOT NULL DEFAULT 0,
  ADD COLUMN "keyRotatedAt"           timestamp(3),
  ADD COLUMN "recoveryAcknowledgedAt" timestamp(3);

-- 2. Member: replace plaintext PII with encrypted bytea + sort helper.
DROP INDEX IF EXISTS "Member_orgId_lastName_idx";

ALTER TABLE "Member"
  DROP COLUMN "firstName",
  DROP COLUMN "lastName",
  DROP COLUMN "phone",
  ADD COLUMN "encFirstName" bytea,
  ADD COLUMN "encLastName"  bytea,
  ADD COLUMN "encPhone"     bytea,
  ADD COLUMN "encStreet"    bytea,
  ADD COLUMN "encCity"      bytea,
  ADD COLUMN "encState"     bytea,
  ADD COLUMN "encZip"       bytea,
  ADD COLUMN "lastNameLc1"  text NOT NULL DEFAULT '?';

CREATE INDEX "Member_orgId_lastNameLc1_idx" ON "Member"("orgId", "lastNameLc1");

-- 3. Photo: encryption flag + encrypted original-name blob.
ALTER TABLE "Photo"
  ADD COLUMN "encrypted"        boolean NOT NULL DEFAULT false,
  ADD COLUMN "encOriginalName"  bytea;
